tabs=[r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type=\"table\" AND name NOT LIKE \"sqlite_%\" ORDER BY name")]
nz={}
for t in tabs:
    n=con.execute(f"SELECT COUNT(*) FROM \"{t}\"").fetchone()[0]
    if n: nz[t]=n
print("NONZERO tables on origin/main:")
for t,n in nz.items(): print(f"{n:6d}  {t}")
print()
print("=== origin/main search_executions: exec_id, slug, results_admitted, admitted_ref_ids ===")
for r in con.execute("SELECT exec_id, slug, results_admitted, admitted_ref_ids, deferred_reason FROM search_executions ORDER BY exec_id"): print(r)
print("=== origin/main search_admissions ===")
for r in con.execute("SELECT * FROM search_admissions ORDER BY exec_id, ref_id"): print(r)
print("=== origin/main search_candidates disposition counts ===")
for r in con.execute("SELECT disposition, locator_status, COUNT(*) FROM search_candidates GROUP BY 1,2"): print(r)
print("=== origin/main search_candidates ADMITTED rows ===")
for r in con.execute("SELECT candidate_id, exec_id, found_under_slug, disposition, locator, locator_status, substr(title,1,50), why_not_admitted, notes FROM search_candidates WHERE disposition=\"ADMITTED\""): print(r)
print("=== origin/main evidence_sources ref_ids ===")
for r in con.execute("SELECT ref_id, tier, verification_status, substr(pub_title,1,60), created_by_session FROM evidence_sources ORDER BY ref_id"): print(r)
print("=== origin/main citation_mining ===")
for r in con.execute("SELECT slug, local_ref_id, global_ref_id, doi, backward, forward, length(connections_produced), created_by_session, deferred_reason FROM citation_mining"): print(r)
print("=== origin/main evidence_source_authors count by ref ===")
for r in con.execute("SELECT ref_id, COUNT(*) FROM evidence_source_authors GROUP BY 1"): print(r)
print("=== origin/main source_slug_links ===")
for r in con.execute("SELECT * FROM source_slug_links"): print(r)
print("=== origin/main evidence_population_match ===")
for r in con.execute("SELECT * FROM evidence_population_match"): print(r)
print("=== origin/main items count, jurisdictional_values count, item_taxonomy_links, term_item_links ===")
for t in ["items","jurisdictional_values","item_taxonomy_links","term_item_links","room_items","conflicts","connections","connection_targets","item_bpc_links","item_population_elaborations","item_audit_runs","spec_value_probes","source_value_extractions","specification_source_links","specifications","reference_stubs","supersession_check","search_coverage","gap_mining","case_studies","economics_entries","reasoning_doc_citations","convergence_assessment","bpc_metadata"]:
    print(t, con.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0])
'

